        QAM1024_Q   = sqrt(1/682)*[11,9,11,9,13,15,13,15,11,9,11,9,13,15,13,15,5,7,5,7,3,1,3,1,5,7,5,7,3,1,3,1,11,9,11,9,13,15,13,15,11,9,11,9,13,15,13,15,5,7,5,7,3,1,3,1,5,7,5,7,3,1,3,1,21,23,21,23,19,17,19,17,21,23,21,23,19,17,19,17,27,25,27,25,29,31,29,31,27,25,27,25,29,31,29,31,21,23,21,23,19,17,19,17,21,23,21,23,19,17,19,17,27,25,27,25,29,31,29,31,27,25,27,25,29,31,29,31,11,9,11,9,13,15,13,15,11,9,11,9,13,15,13,15,5,7,5,7,3,1,3,1,5,7,5,7,3,1,3,1,11,9,11,9,13,15,13,15,11,9,11,9,13,15,13,15,5,7,5,7,3,1,3,1,5,7,5,7,3,1,3,1,21,23,21,23,19,17,19,17,21,23,21,23,19,17,19,17,27,25,27,25,29,31,29,31,27,25,27,25,29,31,29,31,21,23,21,23,19,17,19,17,21,23,21,23,19,17,19,17,27,25,27,25,29,31,29,31,27,25,27,25,29,31,29,31,-11,-9,-11,-9,-13,-15,-13,-15,-11,-9,-11,-9,-13,-15,-13,-15,-5,-7,-5,-7,-3,-1,-3,-1,-5,-7,-5,-7,-3,-1,-3,-1,-11,-9,-11,-9,-13,-15,-13,-15,-11,-9,-11,-9,-13,-15,-13,-15,-5,-7,-5,-7,-3,-1,-3,-1,-5,-7,-5,-7,-3,-1,-3,-1,-21,-23,-21,-23,-19,-17,-19,-17,-21,-23,-21,-23,-19,-17,-19,-17,-27,-25,-27,-25,-29,-31,-29,-31,-27,-25,-27,-25,-29,-31,-29,-31,-21,-23,-21,-23,-19,-17,-19,-17,-21,-23,-21,-23,-19,-17,-19,-17,-27,-25,-27,-25,-29,-31,-29,-31,-27,-25,-27,-25,-29,-31,-29,-31,-11,-9,-11,-9,-13,-15,-13,-15,-11,-9,-11,-9,-13,-15,-13,-15,-5,-7,-5,-7,-3,-1,-3,-1,-5,-7,-5,-7,-3,-1,-3,-1,-11,-9,-11,-9,-13,-15,-13,-15,-11,-9,-11,-9,-13,-15,-13,-15,-5,-7,-5,-7,-3,-1,-3,-1,-5,-7,-5,-7,-3,-1,-3,-1,-21,-23,-21,-23,-19,-17,-19,-17,-21,-23,-21,-23,-19,-17,-19,-17,-27,-25,-27,-25,-29,-31,-29,-31,-27,-25,-27,-25,-29,-31,-29,-31,-21,-23,-21,-23,-19,-17,-19,-17,-21,-23,-21,-23,-19,-17,-19,-17,-27,-25,-27,-25,-29,-31,-29,-31,-27,-25,-27,-25,-29,-31,-29,-31,11,9,11,9,13,15,13,15,11,9,11,9,13,15,13,15,5,7,5,7,3,1,3,1,5,7,5,7,3,1,3,1,11,9,11,9,13,15,13,15,11,9,11,9,13,15,13,15,5,7,5,7,3,1,3,1,5,7,5,7,3,1,3,1,21,23,21,23,19,17,19,17,21,23,21,23,19,17,19,17,27,25,27,25,29,31,29,31,27,25,27,25,29,31,29,31,21,23,21,23,19,17,19,17,21,23,21,23,19,17,19,17,27,25,27,25,29,31,29,31,27,25,27,25,2