  methods
  	function obj = SignalConstellation(ModulationOrder, Method, MUSTIdx, LLRCalcMethod)
        % Generates a QAM or PAM signal constellation object with 
        % corresponding Gray-coded bit mapping. The first argument 
        % represents the modulation order and the second argument the
        % method, either 'QAM' or 'PAM'. For example (4,'QAM'), (256,'QAM')
        % or (2,'PAM'), (16,'PAM')
        obj.ModulationOrder          = ModulationOrder;
        obj.ModulationOrderEffective = ModulationOrder;
        obj.Method                   = Method;
        obj.MUSTIdx                  = MUSTIdx;
        obj.LLRsCalculationMethod    = LLRCalcMethod;
        
        % Gray coded bitmapping
        if strcmp(obj.Method, 'QAM')
            switch ModulationOrder
                case 2
                    I = obj.BPSK_I;
                    Q = obj.BPSK_Q;
                case 4
                    I = obj.QPSK_I;
                    Q = obj.QPSK_Q;
                    if obj.MUSTIdx ~= 0
                        c = obj.c_QPSK(obj.MUSTIdx);
                        d = obj.d_QPSK(obj.MUSTIdx);
                    end
                case 16
                    I = obj.QAM16_I;
                    Q = obj.QAM16_Q;
                    if obj.MUSTIdx ~= 0
                        c = obj.c_QAM16(obj.MUSTIdx);
                        d = obj.d_QAM16(obj.MUSTIdx);     
                    end
                case 64
                    I = obj.QAM64_I;
                    Q = obj.QAM64_Q;
                    if obj.MUSTIdx ~= 0
                        c = obj.c_QAM64(obj.MUSTIdx);
                        d = obj.d_QAM64(obj.MUSTIdx);
                    end
                case 256
                    I = obj.QAM256_I;
                    Q = obj.QAM256_Q;
                case 1024
                    I = obj.QAM1024_I;
                    Q = obj.QAM1024_Q;
                otherwise
                    error('Modulation order not supported.');
            end
            if obj.MUSTIdx == 0
                obj.SymbolMapping = I + 1i*Q;
                obj.BitMapping = Utils.Extras.de2bi(0:obj.ModulationOrder-1, [], 'left-msb');
            else
                obj.ModulationOrderEffective = obj.ModulationOrder *4;
                It = c*(I-d);
                Qt = c*(Q-d);
                % Inner mapping is NearUE, outter mapping is FarUE (restricted to legacy LTE QPSK mapping).
                obj.SymbolMapping = [-It - 1i*Qt; - It + 1i*Qt; + It - 1i*Qt; It + 1i*Qt];
                obj.BitMapping = Utils.Extras.de2bi(0:obj.ModulationOrderEffective-1, [], 'left-msb');
                obj.MUSTNearUEScale = c;
            end          
        elseif strcmp(obj.Method, 'PAM')
            obj.BitMapping = [ones(obj.ModulationOrder/2,1);zeros(obj.ModulationOrder/2,1)];
            for i_temp = 2:log2(obj.ModulationOrder)
                BinaryTemp = obj.BitMapping(1:2:end,i_temp-1);
                obj.BitMapping(:,i_temp) = [BinaryTemp;BinaryTemp(end:-1:1)];
            end
            obj.SymbolMapping = (2*(1:obj.ModulationOrder)-obj.ModulationOrder-1).';
            obj.SymbolMapping = obj.SymbolMapping/sqrt(mean(abs(obj.SymbolMapping).^2));
            % Determine the underlying symbol alphabet and the corresponding
            % bit mapping
            [~,SortOrder] = sort(Utils.Extras.bi2de(obj.BitMapping, 'left-msb'),'ascend');
            obj.SymbolMapping = obj.SymbolMapping(SortOrder);
            obj.BitMapping = obj.BitMapping(SortOrder,:);
        else
           error('Signal constellation method must be QAM or PAM!');
        end

        % For the LLR detection, we determine all data symbols which have a
        % bit value of one (zero) at a certain position

        obj.Implementation.DataSymbolsBitvalueOne   = repmat(obj.SymbolMapping,1,log2(obj.ModulationOrderEffective));
        obj.Implementation.DataSymbolsBitvalueOne   = reshape(obj.Implementation.DataSymbolsBitvalueOne(logical(obj.BitMapping)),obj.ModulationOrderEffective/2,[]);
        obj.Implementation.DataSymbolsBitvalueZero  = repmat(obj.SymbolMapping,1,log2(obj.ModulationOrderEffective));
        obj.Implementation.DataSymbolsBitvalueZero  = reshape(obj.Implementation.DataSymbolsBitvalueZero(not(logical(obj.BitMapping))),obj.ModulationOrderEffective/2,[]);       
    end   
    
    function DataSymbols = Bit2Symbol(obj, PrimaryUEStream, MUSTUEStream)
        % Maps a bit stream to the correpsonding symbol alphabet
        tmpSize = size(PrimaryUEStream);
        if obj.MUSTIdx == 0
            DataSymbols = obj.SymbolMapping(Utils.Extras.bi2de(reshape(PrimaryUEStream(:),log2(obj.ModulationOrderEffective),[])', 'left-msb')+1 );
            DataSymbols = reshape(DataSymbols, tmpSize(1)/log2(obj.ModulationOrderEffective), tmpSize(2) );
        else           
            bits = [reshape(MUSTUEStream', 2, [])' reshape(PrimaryUEStream, [], log2(obj.ModulationOrder))];
            DataSymbols = obj.SymbolMapping(Utils.Extras.bi2de(bits, 'left-msb') + 1);
        end
    end

    function EstimatedBitStream = Symbol2Bit(obj, EstimatedDataSymbols)
        % Maps symbols (nearest neighbor detection) to the corresponding
        % bit stream
        EstimatedDataSymbols = EstimatedDataSymbols(:);
        
        [~,b] = min(abs((repmat(EstimatedDataSymbols,1,obj.ModulationOrderEffective)-repmat((obj.SymbolMapping).',size(EstimatedDataSymbols,1),1)).'));
        EstimatedBitStream = obj.BitMapping(b(:),1:log2(obj.ModulationOrderEffective)).';      
        EstimatedBitStream = EstimatedBitStream(:);
    end
    
    function QuantizedDataSymbols = SymbolQuantization(obj,EstimatedDataSymbols)
        % Performs quantization of the received symbols, that is nearest
        % neighbor detection
        EstimatedDataSymbols = EstimatedDataSymbols(:);

        [~,b] = min(abs((repmat(EstimatedDataSymbols,1,obj.ModulationOrderEffective)-repmat((obj.SymbolMapping).',size(EstimatedDataSymbols,1),1)).'));
        QuantizedDataSymbols = obj.SymbolMapping(b(:),:).';
        QuantizedDataSymbols = QuantizedDataSymbols(:);
    end    
    
    function LLRs = LLR_AWGN(obj, y, Pn)
        % Calculates the LLR for an AWGN channel, that is, y=x+n with y
        % denoting the received data symbol, x the transmitted data symbol
        % and n the Gaussian distributed noise with power Pn

        switch obj.LLRsCalculationMethod
            case 'Exact'
                if numel(Pn)>1
                    PnRepeated = reshape(repmat(Pn.',log2(obj.ModulationOrderEffective)*obj.ModulationOrderEffective/2,1),obj.ModulationOrderEffective/2,[]);
                else 
                    PnRepeated = Pn;
                end 
                ReceivedDataSymbolsRepeated     = reshape(repmat(y.',log2(obj.ModulationOrderEffective)*obj.ModulationOrderEffective/2,1),obj.ModulationOrderEffective/2,[]);
                DataSymbolsBitvalueOneRepeated  = repmat(obj.Implementation.DataSymbolsBitvalueOne,1,length(y));
                DataSymbolsBitvalueZeroRepeated = repmat(obj.Implementation.DataSymbolsBitvalueZero,1,length(y));
                LLRs =  log(sum(exp(-abs(ReceivedDataSymbolsRepeated-DataSymbolsBitvalueOneRepeated).^2./PnRepeated),1) ./ sum(exp(-abs(ReceivedDataSymbolsRepeated-DataSymbolsBitvalueZeroRepeated).^2./PnRepeated),1)).';   
            case 'Max-Log'
                if (strcmp(obj.Method, 'QAM') && obj.ModulationOrderEffective > 1024) || (strcmp(obj.Method, 'PAM') && obj.ModulationOrderEffective > 32) || obj.MUSTIdx ~= 0
                    if numel(Pn)>1
                        PnRepeated = reshape(repmat(Pn.',log2(obj.ModulationOrderEffective)*obj.ModulationOrderEffective/2,1),obj.ModulationOrderEffective/2,[]);
                    else 
                        PnRepeated = Pn;
                    end 
                    ReceivedDataSymbolsRepeated     = reshape(repmat(y.',log2(obj.ModulationOrderEffective)*obj.ModulationOrderEffective/2,1),obj.ModulationOrderEffective/2,[]);
                    DataSymbolsBitvalueOneRepeated  = repmat(obj.Implementation.DataSymbolsBitvalueOne,1,length(y));
                    DataSymbolsBitvalueZeroRepeated = repmat(obj.Implementation.DataSymbolsBitvalueZero,1,length(y));
                    LLRs = (max(-abs(ReceivedDataSymbolsRepeated-DataSymbolsBitvalueOneRepeated).^2./PnRepeated,[],1) - max(-abs(ReceivedDataSymbolsRepeated-DataSymbolsBitvalueZeroRepeated).^2./PnRepeated,[],1)).';
                else
                    if numel(Pn)>1
                        PnRepeated = repmat(Pn.', log2(obj.ModulationOrderEffective),1);
                    else 
                        PnRepeated = Pn;
                    end 
                    LLRs = -obj.piecewiseMaxLog(y.')./PnRepeated(:);
                end
            otherwise
                error(['The LLR calculation method can either be ' char(39) 'Exact' char(39) ' or ' char(39) 'Max-Log' char(39) '.'])
        end
        LLRs(LLRs==Inf)  = 10^10;
        LLRs(LLRs==-Inf) = -10^10;
    end
    
    function LLRs = piecewiseMaxLog(obj, y)
        % A piecewise implementation of the Max-Log approximation for the
        % LLR calculation. It supports regular QAM and PAM orders for up to
        % 1024 (for QAM) and 32 (for PAM), respectively. The implementation
        % is within an error range of 1e-13 to the exact Max-Log for
        % typical input ranges. The implementation is a bit exhaustive;
        % however, the speed gain is definitely worth it. I recorded the
        % following gains compared to exact Max-Log for uniformly
        % distrubited input in the range [-2.5, 2.5] for the both the real
        % and imaginary parts:
        % 
        %    Modulation order        Speed gain
        %   ------------------      ------------
        %         BPSK                  2x
        %         4-QAM                 7x
        %         16-QAM                8x
        %         64-QAM                40x
